def summarise_match(rounds, target=3):
    result = {"left": 0, "right": 0, "played": 0, "winner": None}
    for side in rounds:
        if side != "left" and side != "right":
            raise ValueError("Unknown rally winner")
        result[side] += 1
        result["played"] += 1
        if result[side] >= target:
            result["winner"] = side
            break
    return result

rounds = ["left", "right", "left", "left", "right"]
summary = summarise_match(rounds)
print(summary)
